import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import StratifiedKFold
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows significant association with outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'expression':
            # Calculate effect size (mean difference)
            y0_mean = np.mean(feats.x[feats.y == 0, i])
            y1_mean = np.mean(feats.x[feats.y == 1, i])
            effect_size = y1_mean - y0_mean

            # Welch's t-test
            t_stat, p_val = stats.ttest_ind(
                feats.x[feats.y == 0, i], 
                feats.x[feats.y == 1, i], 
                equal_var=False
            )

            if abs(effect_size) > 0.5 and p_val < 0.05:
                effects.append((fid, effect_size, abs(t_stat), p_val))

    # Sort by effect strength (t-statistic)
    effects.sort(key=lambda x: x[2], reverse=True)

    # If no strong effects found, return empty design
    if not effects:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Find correlated features to avoid near-duplicates
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i < j:
                corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
                if abs(corr) >= 0.6:
                    correlations[(fid1, fid2)] = abs(corr)

    # Build set of features to consider
    candidates = [f[0] for f in effects[:10]]  # Top 10 candidates

    # Remove near-duplicates
    selected_features = set()
    for fid in candidates:
        is_duplicate = False
        for selected_fid in selected_features:
            if (fid, selected_fid) in correlations or (selected_fid, fid) in correlations:
                if correlations.get((fid, selected_fid), correlations.get((selected_fid, fid), 0)) >= 0.6:
                    is_duplicate = True
                    break
        if not is_duplicate:
            selected_features.add(fid)

    # Try to build a model with these features
    if len(selected_features) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check stratum consistency using stratified CV
    skf = StratifiedKFold(n_splits=3, shuffle=True, random_state=42)
    cv_scores = []

    for train_idx, test_idx in skf.split(feats.x, feats.y):
        X_train = feats.x[train_idx]
        y_train = feats.y[train_idx]
        X_test = feats.x[test_idx]
        y_test = feats.y[test_idx]

        # Fit logistic regression
        model = LogisticRegression(penalty='l2', C=1.0, solver='liblinear')
        model.fit(X_train[:, [feats.column(fid) for fid in selected_features]], y_train)
        score = model.score(X_test[:, [feats.column(fid) for fid in selected_features]], y_test)
        cv_scores.append(score)

    # If CV scores are not significantly different from random, no mechanism
    if np.mean(cv_scores) < 0.6:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Return top features as drivers
    drivers = tuple([fid for fid in selected_features][:MAX_DRIVERS])
    columns = tuple(selected_features)

    # No products needed for this simple case
    products = ()

    # Simple weighted score based on effect sizes
    loadings = {}
    for fid in selected_features:
        i = feats.column(fid)
        effect = np.mean(feats.x[feats.y == 1, i]) - np.mean(feats.x[feats.y == 0, i])
        loadings[fid] = effect

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

